	var laggedEMA float64
	var tempReal float64
	var optInK_1 float64
	var emaBeta float64
	var i int32
	var today int32
	var outIdx int32
	var lookbackTotal int32
	var emaRing []float64
	var emaRing_Idx int32
	var maxIdx_emaRing int32
	maxIdx_emaRing = 31
	if len(inHigh) > IndexMax+1 {
		return OutOfRangeEndIndex
	}
	historyLen := int32(len(inHigh))
	endIdx := historyLen - 1
	if len(inLow) != len(inHigh) {
		return BadParam
	}
